mapper.select:
SELECT o.id, o.creator_id, sc.name AS creator_name, o.approver_id, sa.name AS approver_name, o.status, o.remark, o.create_time, o.approve_time, COUNT(l.product_id) AS item_count, COALESCE(SUM(l.quantity), 0) AS total_quantity FROM stock_replenish_order o LEFT JOIN stock_replenish_log l ON l.id = o.id LEFT JOIN staff sc ON sc.id = o.creator_id LEFT JOIN staff sa ON sa.id = o.approver_id
o.status = #{status}
GROUP BY o.id, o.creator_id, sc.name, o.approver_id, sa.name, o.status, o.remark, o.create_time, o.approve_time ORDER BY o.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM stock_replenish_order o


        o.status = #{status}
